// Turn the API response into one Discord message with one embed.
const settings = $('Settings').first().json;
const topN = Math.min(Math.max(Number(settings.top_n) || 5, 1), 10);
const repos = ($input.first().json.results || []).slice(0, topN);
if (repos.length === 0) {
  return []; // nothing came back today; send nothing
}

const lines = repos.map((repo, i) => {
  const text = repo.description || '';
  const about = text.length > 180 ? `${text.slice(0, 179).trimEnd()}…` : text;
  const stars = repo.stars_today ? ` · +${repo.stars_today} stars today` : '';
  // "1\\." keeps Discord from turning the line into a numbered list.
  return `${i + 1}\\. **[${repo.full_name}](${repo.url})**${stars}\n${about}`;
});

const payload = {
  embeds: [{
    title: 'GitHub trending today',
    url: 'https://github.com/trending',
    color: 0x0ACAB5,
    description: lines.join('\n\n').slice(0, 4000),
    footer: { text: 'Data via EveryInfra' },
  }],
  allowed_mentions: { parse: [] },
};
return [{ json: { payload } }];
